class Solution {
public:
    vector<int> reverseSubarrays(vector<int>& nums, int k) {
        int len = (int)nums.size() / k;
        for (int start = 0; start < (int)nums.size(); start += len)
            reverse(nums.begin() + start, nums.begin() + start + len);
        return nums;
    }
};
